const fs = require('node:fs')
const path = require('node:path')

// Literal imports let Next record each theme's chunk in the HTML and preload it
// before hydration. Keep this in sync with the same directory scan as THEMES.
function writeThemeRegistry(root, themes) {
  const source = [
    '// Generated by next.config.js from the themes directory. Do not edit by hand.',
    "import dynamic from 'next/dynamic'",
    "import { renderThemeModule, ThemeLoading } from './renderThemeModule'",
    '',
    'const themeComponents = {',
    ...themes.map(name =>
      `  ${JSON.stringify(name)}: dynamic(() => import(${JSON.stringify(`./${name}`)}).then(renderThemeModule), { loading: ThemeLoading }),`
    ),
    '}',
    '',
    'export default themeComponents',
    ''
  ].join('\n')
  const target = path.join(root, 'themes/themeComponents.generated.js')
  if (!fs.existsSync(target) || fs.readFileSync(target, 'utf8') !== source) {
    fs.writeFileSync(target, source)
  }
}

module.exports = { writeThemeRegistry }
